\[ \begin{aligned} I_{xx} &amp;= \frac{m (y^2 + z^2)}{12} \\ I_{yy} &amp;= \frac{m (z^2 + x^2)}{12} \\ I_{zz} &amp;= \frac{m (x^2 + y^2)}{12} \\ I_{xy} &amp;= I_{yz} = I_{zx} = 0 \\ \end{aligned} \] <pre><code>&lt;xacro:macro name="box_inertia" params="x y z m"&gt;
  &lt;inertia ixx="${m * (y*y + z*z) / 12}" ixy="0.0" ixz="0.0" iyy="${m * (z*z + x*x) / 12}" iyz="0.0" izz="${m * (x*x + y*y) / 12}"/&gt;
&lt;/xacro:macro&gt;
</code></pre>

\[ \begin{aligned} I_{xx} &amp;= I_{yy} = m (\frac{r^2}{4} + \frac{h^2}{12}) \\ I_{zz} &amp;= \frac{m r^2}{2} \\ I_{xy} &amp;= I_{yz} = I_{zx} = 0 \\ \end{aligned} \] <pre><code>&lt;xacro:macro name="cylinder_inertia" params="r h m"&gt;
